import com.modelgate.platform.dto.ApiResponse;
import com.modelgate.platform.dto.ProviderRegisterRequest;
import com.modelgate.platform.service.ProviderService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/providers")
public class ProviderController {

    @Autowired
    private ProviderService providerService;

    @PostMapping
    public ResponseEntity<ApiResponse<Map<String, Object>>> register(
            @RequestBody ProviderRegisterRequest request,
            Authentication auth) {
        if (isBlank(request.getName()) || isBlank(request.getBaseUrl())
                || isBlank(request.getApiKey()) || isBlank(request.getModelId())) {
            return ResponseEntity.badRequest()
                    .body(ApiResponse.error(400, "name、baseUrl、apiKey、modelId不能为空"));
        }
        Map<String, Object> data = providerService.register(
                auth.getName(), request.getName(), request.getBaseUrl(),
                request.getApiKey(), request.getModelId());
        return ResponseEntity.ok(ApiResponse.success("注册成功", data));
    }

    @GetMapping
    public ResponseEntity<ApiResponse<List<Map<String, Object>>>> list(Authentication auth) {
        List<Map<String, Object>> data = providerService.listProviders(auth.getName());
        return ResponseEntity.ok(ApiResponse.success("success", data));
    }

    @GetMapping("/{id}")
    public ResponseEntity<ApiResponse<Map<String, Object>>> detail(
            @PathVariable Long id, Authentication auth) {
        Map<String, Object> data = providerService.getProvider(id, auth.getName());
        if (data == null) {
            return ResponseEntity.status(404)
                    .body(ApiResponse.error(404, "Provider不存在或无权限"));
        }
        return ResponseEntity.ok(ApiResponse.success("success", data));
    }

    @PostMapping("/{id}/validate")
    public ResponseEntity<ApiResponse<Map<String, Object>>> validate(
            @PathVariable Long id, Authentication auth) {
        Map<String, Object> data = providerService.validateProvider(id, auth.getName());
        if (data == null) {
            return ResponseEntity.status(404)
                    .body(ApiResponse.error(404, "Provider不存在或无权限"));
        }
        return ResponseEntity.ok(ApiResponse.success("验证完成", data));
    }

    private static boolean isBlank(String s) {
        return s == null || s.isBlank();
    }
}"
}

