30	        if (isBlank(request.getName()) || isBlank(request.getBaseUrl())
31	                || isBlank(request.getApiKey()) || isBlank(request.getModelId())) {
32	            return ResponseEntity.badRequest()
33	                    .body(ApiResponse.error(400, "name、baseUrl、apiKey、modelId不能为空"));
